{"command": "python3 - <<'PY'
import json
p=json.load(open('/workspace/contracts/openapi.contract.json'))
print('paths',len(p['paths']))
for path,item in p['paths'].items():
  for method,op in item.items():
    if method.startswith('x-'): continue
    rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
    print(f"{method.upper():6} {path:42} {op.get('operationId')}")
    if rb:
      print('  body:', json.dumps(rb,separators=(',',':'))[:700])
    params=[]
    for x in op.get('parameters',[]): params.append(f"{x['name']}({x['in']}) req={x.get('required',False)}")
    if params: print('  params:', ', '.join(params))
    print('  success:', ', '.join(k for k in op.get('responses',{}) if k.startswith('2')))
print('\ncomponents schemas:', ', '.join(p.get('components',{}).get('schemas',{})))
PY", "security_risk": "LOW", "summary": "Summarize API paths requests and responses"}

