import {useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import './styles.css';
const api='/api';
type User={userId:string;username:string;fullName?:string;roles:string[];activeRole:string;roleSelectionRequired:boolean};
type Boot={user:User;serverTime:string;requesterSamples?:any[];operations?:any};
async function call(path:string,options:RequestInit={},token?:string){const r=await fetch(api+path,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});const b=await r.json();if(!r.ok)throw Error(b.code||b.error||'Request failed');return b.data}
function Login({done}:{done:(t:string,b:Boot)=>void}){const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();try{const a=await call('/authenticate-user',{method:'POST',body:JSON.stringify({username,password})});done(a.sessionToken,await call('/ui/bootstrap',{},a.sessionToken))}catch{setError('Invalid username or password')}}return <main className="auth"><form className="login card" onSubmit={submit}><div className="logo">LAB<span>FLOW</span></div><h1>Sample logistics</h1><p>Pickup, custody, and laboratory delivery.</p><label htmlFor="username">Username</label><input id="username" value={username} onChange={e=>setUsername(e.target.value)} required/><label htmlFor="password">Password</label><input id="password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required/>{error&&<div className="error" role="alert">{error}</div>}<button>Sign in</button></form></main>}
function App(){const [token,setToken]=useState(localStorage.getItem('token')||''),[boot,setBoot]=useState<Boot|null>(null),[tab,setTab]=useState('Overview'),[audit,setAudit]=useState<any[]>([]);useEffect(()=>{if(token)call('/ui/bootstrap',{},token).then(setBoot).catch(()=>{setToken('');localStorage.removeItem('token')})},[token]);if(!token||!boot)return <Login done={(t,b)=>{localStorage.setItem('token',t);setToken(t);setBoot(b)}}/>;const refresh=()=>call('/ui/bootstrap',{},token).then(setBoot);const choose=async(e:React.ChangeEvent<HTMLSelectElement>)=>{await call('/select-active-role',{method:'POST',body:JSON.stringify({role:e.target.value})},token);refresh()};const signout=()=>{localStorage.removeItem('token');setToken('');setBoot(null)};const openAudit=async()=>{setTab('Audit history');const a=await call('/search-audit-trail',{method:'POST',body:JSON.stringify({limit:50,order:'newest_first'})},token);setAudit(a.entries)};return <div className="app"><header><div className="logo">LAB<span>FLOW</span></div><div className="head-actions"><label htmlFor="role">Working as</label><select id="role" value={boot.user.activeRole} onChange={choose}>{boot.user.roles.map(r=><option key={r}>{r}</option>)}</select><button className="outline" onClick={signout}>Sign out</button></div></header><div className="body"><aside><div className="identity"><div className="avatar">{(boot.user.fullName||boot.user.username)[0].toUpperCase()}</div><b>{boot.user.fullName||boot.user.username}</b><small>{boot.user.activeRole.replaceAll('_',' ')}</small></div><nav aria-label="Main navigation">{['Overview','My work','Samples','Live map'].map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}<button className={tab==='Audit history'?'active':''} onClick={openAudit}>Audit history</button></nav><footer>● Network online<br/><small>Synced {new Date(boot.serverTime).toLocaleTimeString()}</small></footer></aside><main className="main"><div className="title"><div><small>CONTROL CENTER</small><h1>{tab}</h1><p>Track every handoff from collection to receipt.</p></div><span className="online">● All systems operational</span></div>{tab==='Overview'&&<Overview boot={boot} refresh={refresh}/>} {tab==='My work'&&<Work token={token} role={boot.user.activeRole}/>} {tab==='Samples'&&<Samples boot={boot} token={token}/>} {tab==='Live map'&&<Map boot={boot}/>} {tab==='Audit history'&&<Audit entries={audit}/>}</main></div></div>}
function Overview({boot,refresh}:{boot:Boot;refresh:()=>void}){const o=boot.operations||{},s=o.samples||[];return <><div className="metrics"><Metric label="Active samples" value={s.filter((x:any)=>!['received','cancelled'].includes(x.status))}/><Metric label="Awaiting collection" value={s.filter((x:any)=>x.status==='awaiting_collection')} tone="amber"/><Metric label="Exceptions" value={o.exceptions||[]} tone="red"/><Metric label="Workers online" value={(o.workers||[]).filter((x:any)=>x.available)} tone="violet"/></div><div className="columns"><section className="card panel"><div className="panel-title"><h2>Sample activity</h2><button className="link" onClick={refresh}>Refresh</button></div>{s.length?s.slice(0,8).map((x:any)=><div className="list-row" key={x.sampleId}><div><b>{x.sampleId.slice(0,8)}…</b><small>{x.status.replaceAll('_',' ')}</small></div><span className={x.locationStale?'tag stale':'tag'}>{x.locationStale?'Location stale':'Tracking live'}</span></div>):<Empty text="No samples are currently in the network."/>}</section><section className="card panel"><h2>Network health</h2><div className="health"><div><b>{(o.locations||[]).length}</b><small>Locations</small></div><div><b>{(o.connections||[]).length}</b><small>Connections</small></div><div><b>{o.assignmentCountSpread||0}</b><small>Workload spread</small></div></div><div className="map-mini">LOCAL PMTILES MAP<br/><small>Routes and custody locations</small></div></section></div></>}
function Metric({label,value,tone='teal'}:{label:string;value:any;tone?:string}){return <div className={`card metric ${tone}`}><small>{label}</small><b>{Array.isArray(value)?value.length:value}</b><span>Updated just now</span></div>};function Empty({text}:{text:string}){return <div className="empty">{text}</div>}
function Work({token,role}:{token:string;role:string}){const [w,setW]=useState<any>();useEffect(()=>{call('/list-role-work',{method:'POST',body:JSON.stringify({})},token).then(setW)},[token]);return <section className="card panel"><h2>My current work</h2><p>Role: {role.replaceAll('_',' ')}</p>{w?.pending?.length?w.pending.map((x:any)=><div className="work" key={x.assignmentId}><b>{x.kind}</b><span>Sample {x.sampleId.slice(0,8)}…</span><em>{x.status}</em></div>):<Empty text="No assignments are currently scoped to this role."/>}</section>}
function Samples({boot,token}:{boot:Boot;token:string}){const xs=boot.requesterSamples||boot.operations?.samples||[],[item,setItem]=useState<any>();return <section className="card panel"><div className="panel-title"><h2>Samples</h2><span>{xs.length} visible</span></div>{xs.length?<div className="sample-grid">{xs.map((x:any)=><button className="sample" key={x.sampleId} onClick={()=>call('/read-sample-state/'+x.sampleId,{},token).then(setItem)}><b>Sample {x.sampleId.slice(0,8)}…</b><span>{x.status.replaceAll('_',' ')}</span><small>{x.locationStale?'Location stale':'Location current'}</small></button>)}</div>:<Empty text="No samples are visible yet."/>}{item&&<div className="detail"><h3>Status timeline</h3><b>{item.state.status}</b>{item.timeline.map((x:any)=><div className="event" key={x.eventId}><i/> {x.action.replaceAll('_',' ')} <small>{new Date(x.occurredAt).toLocaleString()}</small></div>)}</div>}</section>}
function Map({boot}:{boot:Boot}){const ls=boot.operations?.locations||[];return <section className="card panel map"><div className="map-large"><b>LIVE NETWORK MAP</b><p>MapLibre · local PMTiles assets</p>{ls.map((x:any)=><span className="marker" key={x.id} title={x.name}>●</span>)}</div><div><h2>Network locations</h2>{ls.map((x:any)=><div className="location" key={x.id}><i/> <b>{x.name}</b><small>{Object.keys(x.functions||{}).filter(k=>x.functions[k]).join(' · ')}</small></div>)}</div></section>}
function Audit({entries}:{entries:any[]}){return <section className="card panel"><div className="panel-title"><h2>Audit history</h2><span>Durable events</span></div>{entries.length?entries.map(x=><div className="audit" key={x.auditId}><b>✓</b><div><strong>{x.action.replaceAll('_',' ')}</strong><small>{x.entityType} · {x.entityId.slice(0,12)}</small></div><time>{new Date(x.occurredAt).toLocaleString()}</time></div>):<Empty text="No audit events match the current search."/>}</section>}
createRoot(document.getElementById('root')!).render(<App/>);
EOF

